import sys

def solve():
    s = sys.stdin.readline().strip()
    best = 1
    cur = 1
    for i in range(1, len(s)):
        if s[i] == s[i - 1]:
            cur += 1  # 같은 문자가 이어지면 현재 연속 길이를 늘린다
            best = max(best, cur)
        else:
            cur = 1  # 다른 문자가 나오면 연속 길이를 다시 1부터 센다
    print(best)

solve()

