import sys
from collections import deque

def solve():
    data = sys.stdin.read().split("\n")
    r, c, k = map(int, data[0].split())
    grid = [data[1 + i] for i in range(r)]

    # dist[y][x][b]: 벽을 b번 부순 상태로 (y, x)까지 오는 데 필요한 최소 이동 횟수
    dist = [[[-1] * (k + 1) for _ in range(c)] for _ in range(r)]
    dist[0][0][0] = 0
    q = deque([(0, 0, 0)])

    while q:
        y, x, b = q.popleft()
        if y == r - 1 and x == c - 1:
            print(dist[y][x][b])
            return
        for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            ny, nx = y + dy, x + dx
            if not (0 <= ny < r and 0 <= nx < c):
                continue
            if grid[ny][nx] == '.':
                if dist[ny][nx][b] == -1:
                    dist[ny][nx][b] = dist[y][x][b] + 1
                    q.append((ny, nx, b))
            else:
                if b + 1 <= k and dist[ny][nx][b + 1] == -1:
                    dist[ny][nx][b + 1] = dist[y][x][b] + 1  # 벽을 하나 더 부수고 진입
                    q.append((ny, nx, b + 1))

    print(-1)

solve()

import sys

def solve():
    data = sys.stdin.read().split()
    idx = 0
    n = int(data[idx]); idx += 1
    m = int(data[idx]); idx += 1

    INF = float('inf')
    dist = [[INF] * (n + 1) for _ in range(n + 1)]
    for i in range(1, n + 1):
        dist[i][i] = 0

    for _ in range(m):
        a = int(data[idx]); b = int(data[idx + 1]); w = int(data[idx + 2])
        idx += 3
        if w < dist[a][b]:  # 같은 두 정점 사이에 여러 간선이 있으면 가장 작은 가중치만 남긴다
            dist[a][b] = w
            dist[b][a] = w

    # 플로이드-워셜: 경유지 k를 하나씩 늘려가며 모든 정점 쌍의 최단 거리를 갱신한다.
    for k in range(1, n + 1):
        dk = dist[k]
        for i in range(1, n + 1):
            dik = dist[i][k]
            if dik == INF:
                continue
            di = dist[i]
            for j in range(1, n + 1):
                nd = dik + dk[j]
                if nd < di[j]:
                    di[j] = nd

    ans = 0
    for i in range(1, n + 1):
        for j in range(1, n + 1):
            if i != j:
                ans = max(ans, dist[i][j])

    print(ans)

solve()
